// Synthetic catalog-only native fixture. No Codex, providers, Firebase or real user data.
import express from 'express';import http from 'node:http';import {WebSocketServer,WebSocket} from 'ws';import {catalogFields,compareSessionWork} from '../../server/session-catalog.mjs';
const app=express();app.use(express.json());const server=http.createServer(app),wss=new WebSocketServer({noServer:true});const token='synthetic-catalog-only',key='synthetic-catalog-control',epoch=Date.now();let partial=false;const requests=[];
const users=[...Array.from({length:12},(_,i)=>({id:`recent-${String(i+1).padStart(2,'0')}`,name:`Recent user task ${String(i+1).padStart(2,'0')}`,createdAt:Math.floor((epoch-7*86400000)/1000),recencyAt:Math.floor((epoch-i*3600000)/1000)})),...Array.from({length:262},(_,i)=>({id:`old-${String(i+1).padStart(3,'0')}`,name:`Dormant history ${String(i+1).padStart(3,'0')}`,createdAt:Math.floor((epoch-180*86400000)/1000),recencyAt:Math.floor((epoch-(30+i)*86400000)/1000)}))];
let threads=users.map((t,i)=>({...t,updatedAt:Math.floor(epoch/1000)+i,source:'cli',cwd:'/synthetic/catalog',status:{type:i<2?'active':'idle'},preview:`Own available work for ${t.name}.`,watched:i===0}));
for(let i=1;i<=6;i++)threads.push({...threads[0],id:`agent-${i}`,name:`Delegated task ${i}`,parentThreadId:i===6?'agent-1':i<4?'recent-01':'recent-02',source:{subAgent:{thread_spawn:{parent_thread_id:i===6?'agent-1':i<4?'recent-01':'recent-02'}}},agentNickname:`Catalog Scout ${i}`,agentRole:'explorer',canAcceptDirectInput:i===5,status:{type:i===1?'active':'idle'},preview:`Synthetic delegated result ${i}; parent retains ownership.`});
const emit=value=>{for(const ws of wss.clients)if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify(value));};
app.get('/health',(_req,res)=>res.json({ok:true,synthetic:true}));app.use('/fixture',(req,res,next)=>req.headers['x-fixture-key']===key?next():res.sendStatus(403));
app.get('/fixture/state',(_req,res)=>res.json({partial,requests,primaries:users.length,children:6}));
app.post('/fixture/action',(req,res)=>{const action=req.body.action;
 if(action==='metadata'){threads=threads.map((t,i)=>({...t,updatedAt:Math.floor(Date.now()/1000)+i})).reverse();for(const t of threads)emit({type:'sessionActivity',threadId:t.id,status:t.status});}
 else if(action==='reconnect')for(const ws of wss.clients)ws.close(1012,'Synthetic catalog reconnect');
 else if(action==='partial')partial=true;
 else if(action==='complete')partial=false;
 else if(action==='result'){const id=req.body.id||'agent-1',preview=req.body.text||'New useful synthetic agent result; review through parent.';threads=threads.map(t=>t.id===id?{...t,preview}:t);emit({type:'sessionPreview',threadId:id,preview,previewRole:'assistant',previewKind:'message',activityAt:Date.now()});}
 else if(action==='user'){const id=req.body.id||'old-001',at=Date.now();threads=threads.map(t=>t.id===id?{...t,recencyAt:Math.floor(at/1000),activityAt:at,status:{type:'active'},preview:'New deliberate synthetic user work.'}:t);emit({type:'sessionActivity',threadId:id,activityAt:at,status:{type:'active'}});}
 else return res.status(400).json({error:'Unknown action'});res.json({ok:true});});
app.post('/api/pair',(req,res)=>req.body.code==='CATALOG'?res.json({token,id:'synthetic-catalog',host:'Synthetic catalog review',local:true}):res.sendStatus(401));app.use('/api',(req,res,next)=>req.headers.authorization===`Bearer ${token}`?next():res.sendStatus(401));
app.get('/api/status',(_req,res)=>res.json({connected:true,problem:null,host:'Synthetic catalog review',deviceId:'synthetic-catalog',local:true}));
app.get('/api/threads',(req,res)=>{requests.push({method:'list',cursor:req.query.cursor||null,search:req.query.search||null});const sorted=threads.filter(t=>!t.parentThreadId).sort(compareSessionWork),start=Number(req.query.cursor||0),count=req.query.search?100:32;let rows=req.query.search?threads.filter(t=>t.name.toLowerCase().includes(String(req.query.search).toLowerCase())):sorted.slice(start,start+count);if(!start&&!req.query.search)rows=rows.concat(threads.filter(t=>t.parentThreadId));if(partial)rows=rows.slice(0,4);res.json({threads:rows.map(t=>({...t,...catalogFields(t),previewRole:'assistant',previewKind:'message',archived:false})),nextCursor:req.query.search?null:start+count<sorted.length?String(start+count):null,refreshPending:partial});});
app.get('/api/threads/:id',(req,res)=>{const thread=threads.find(t=>t.id===req.params.id);if(!thread)return res.status(404).json({error:'Unknown synthetic task'});requests.push({method:'read',id:thread.id});res.json({thread:{...thread,...catalogFields(thread)},timeline:{rows:[{id:`${thread.id}-answer`,turnId:'fixture-turn',kind:'message',role:'assistant',text:`Correct synthetic conversation for ${thread.name}. ${thread.preview}`}],hasEarlier:false},revision:1,notes:[],pending:[],notifications:[],outgoing:[],watched:false});});
app.post('/api/threads/:id/reply',(req,res)=>{const thread=threads.find(t=>t.id===req.params.id);requests.push({method:'reply',id:req.params.id,text:req.body.text});if(thread?.parentThreadId&&thread.canAcceptDirectInput!==true)return res.status(409).json({error:'Guide through the parent task.'});res.status(202).json({id:req.body.id,state:'queued'});});
app.get('/api/coordinator/reports',(_req,res)=>res.json({reports:[],latest:null,unreadCount:0,hasEarlier:false}));app.post('/api/voice/start',(req,res)=>{requests.push({method:'voice',id:req.body.threadId??null});res.status(503).json({error:'Synthetic capture target checked; providers blocked'});});
for(const route of ['notifications','attention'])app.get(`/api/${route}`,(_req,res)=>res.json({notifications:[]}));app.get('/api/activity',(_req,res)=>res.json({items:[]}));app.get('/api/projects',(_req,res)=>res.json({projects:[]}));app.get('/api/app/update',(_req,res)=>res.json({available:false}));app.post('/api/device/push',(_req,res)=>res.json({ok:true}));app.use('/api',(_req,res)=>res.status(503).json({error:'Fixture blocks execution and other operations'}));
server.on('upgrade',(req,socket,head)=>{if(req.url!=='/events'||req.headers.authorization!==`Bearer ${token}`){socket.destroy();return;}wss.handleUpgrade(req,socket,head,ws=>{ws.send(JSON.stringify({type:'status',connected:true,problem:null}));wss.emit('connection',ws,req);});});
server.listen(Number(process.env.CATALOG_FIXTURE_PORT||19995),'127.0.0.1',()=>console.log('Synthetic catalog fixture ready on loopback:'+server.address().port));for(const sig of ['SIGINT','SIGTERM'])process.once(sig,()=>{for(const ws of wss.clients)ws.terminate();wss.close();server.close(()=>process.exit(0));});
